:host {
  display: block;
  padding: 2rem;
  max-width: 1200px;
  margin: 0 auto;
  text-align: center;
}

$seat-w: 2.1rem;
$label-w: 1.6rem;
$gap: 0.25rem;

.auditorium {
  display: inline-block;
}

.screen {
  background: #333;
  color: #fff;
  text-align: center;
  letter-spacing: 0.3em;
  padding: 0.5rem;
  margin-bottom: 1rem;
  border-radius: 4px;
}

.seat-map {
  display: flex;
  flex-direction: column;
  gap: $gap;
}

.seat-row {
  display: grid;
  grid-template-columns:
    #{$label-w} repeat(4, #{$seat-w}) calc(#{$seat-w} * 2) repeat(16, #{$seat-w}) calc(#{$seat-w} * 2) repeat(4, #{$seat-w})
    #{$label-w};
  align-items: center;
  gap: $gap;
}

.row-label {
  text-align: center;
  font-size: 0.85rem;
  color: #555;
}

.aisle {
  width: 100%;
}

.seat,
.couch {
  height: $seat-w;
  border: none;
  border-radius: 4px;
  font-size: 0.75rem;
  color: #fff;
  cursor: pointer;
  padding: 0;

  &.available {
    background-color: #2e7d32;
  }

  &.selected {
    background-color: #f9a825;
  }

  &.unavailable {
    background-color: #c62828;
    cursor: not-allowed;
  }

  &.accessible {
    background-color: #1565c0;
  }
}

.couch {
  border-radius: 6px;
  font-weight: 600;
}

.legend {
  display: flex;
  justify-content: center;
  gap: 1.5rem;
  margin: 1.5rem 0;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.swatch {
  display: inline-block;
  width: 1rem;
  height: 1rem;
  border-radius: 3px;

  &.available {
    background-color: #2e7d32;
  }

  &.selected {
    background-color: #f9a825;
  }

  &.unavailable {
    background-color: #c62828;
  }

  &.accessible {
    background-color: #1565c0;
  }
}

.selected-seats {
  margin-bottom: 1.5rem;
}

.actions {
  display: flex;
  justify-content: center;
  gap: 1rem;
}

