// Minimal CDP driver using Node's native WebSocket + fetch (no playwright).
const CHROME = '/opt/ms-playwright/chromium-1234/chrome-linux/chrome';
const { spawn } = require('child_process');
const fs = require('fs');

const PORT = 9333;

async function waitForDebugger() {
  for (let i = 0; i < 60; i++) {
    try {
      const res = await fetch(`http://127.0.0.1:${PORT}/json/version`);
      if (res.ok) return;
    } catch {
      // not ready yet
    }
    await new Promise((r) => setTimeout(r, 500));
  }
  throw new Error('chrome debugger did not start');
}

async function main() {
  const chrome = spawn(
    CHROME,
    [
      '--headless=new',
      '--no-sandbox',
      '--disable-gpu',
      `--remote-debugging-port=${PORT}`,
      '--remote-debugging-address=127.0.0.1',
      'about:blank',
    ],
    { stdio: 'ignore' },
  );
  chrome.unref();

  await waitForDebugger();

