const { spawn } = require('child_process');
const fs = require('fs');

const PORT = 9333;

async function waitForDebugger() {
  for (let i = 0; i < 60; i++) {
    try {
      const res = await fetch(`http://127.0.0.1:${PORT}/json/version`);
      if (res.ok) return;
    } catch {
      // not ready yet
    }
    await new Promise((r) => setTimeout(r, 300));
  }
  throw new Error('chrome debugger did not start');
}

async function withPage(fn) {
  const chrome = spawn(
    CHROME,
    [
      '--headless=new',
      '--no-sandbox',
      '--disable-gpu',
      '--window-size=1280,900',
      `--remote-debugging-port=${PORT}`,
      '--remote-debugging-address=127.0.0.1',
      'about:blank',
    ],
    { stdio: 'ignore' },
  );

  try {
    await waitForDebugger();
    const targets = await fetch(`http://127.0.0.1:${PORT}/json`).then((r) => r.json());
    const target = targets.find((t) => t.type === 'page') ?? targets[0];
    const ws = new WebSocket(target.webSocketDebuggerUrl);

    await new Promise((resolve, reject) => {
      ws.addEventListener('open', resolve);
      ws.addEventListener('error', reject);
    });

    let id = 0;
    const pending = new Map();
    const consoleMessages = [];
    let loadResolvers = [];

    ws.addEventListener('message', (event) => {
      const msg = JSON.parse(event.data);
      if (msg.id !== undefined && pending.has(msg.id)) {
        const { resolve, reject } = pending.get(msg.id);
        pending.delete(msg.id);
        if (msg.error) reject(new Error(JSON.stringify(msg.error)));
        else resolve(msg.result);
      } else if (msg.method === 'Runtime.consoleAPICalled') {
        const text = (msg.params.args || []).map((a) => a.value ?? a.description ?? '').join(' ');
        consoleMessages.push(`[${msg.params.type}] ${text}`);
      } else if (msg.method === 'Runtime.exceptionThrown') {
        consoleMessages.push(`[exception] ${JSON.stringify(msg.params.exceptionDetails)}`);
      } else if (msg.method === 'Page.loadEventFired') {
        loadResolvers.forEach((r) => r());
        loadResolvers = [];
      }
    });

    function send(method, params = {}) {
      const thisId = ++id;
      return new Promise((resolve, reject) => {
        pending.set(thisId, { resolve, reject });
        ws.send(JSON.stringify({ id: thisId, method, params }));
      });
    }

    await send('Page.enable');
    await send('Runtime.enable');

    const page = {
      async navigate(url) {
        const loaded = new Promise((resolve) => loadResolvers.push(resolve));
        await send('Page.navigate', { url });
        await loaded;
      },
      async evaluate(expression) {
        const result = await send('Runtime.evaluate', {
          expression,
          returnByValue: true,
          awaitPromise: true,
        });
        if (result.exceptionDetails) {
          throw new Error(JSON.stringify(result.exceptionDetails));
        }
        return result.result.value;
      },
      async waitFor(expression, timeoutMs = 10000) {
        const start = Date.now();
        while (Date.now() - start < timeoutMs) {
          const ok = await page.evaluate(expression).catch(() => false);
          if (ok) return;
          await new Promise((r) => setTimeout(r, 200));
        }
        throw new Error(`waitFor timed out: ${expression}`);
      },
      async screenshot(path) {
        const result = await send('Page.captureScreenshot', { format: 'png' });
        fs.writeFileSync(path, Buffer.from(result.data, 'base64'));
      },
      consoleMessages,
    };

    return await fn(page);
  } finally {
    chrome.kill('SIGKILL');
  }
}

module.exports = { withPage };

