const { withPage } = require('/tmp/cdp-driver.js');

withPage(async (page) => {
  await page.navigate('http://localhost:4200/screenings/1/seats');
  await page.waitFor(`document.querySelector('[data-testid="seat-map-title"]') !== null`);
  await new Promise((r) => setTimeout(r, 500));
  const info = await page.evaluate(`({
    seats: document.querySelectorAll('[data-testid="seat"]').length,
    couches: document.querySelectorAll('[data-testid="couch"]').length,
    aisles: document.querySelectorAll('[data-testid="aisle"]').length,
    rows: document.querySelectorAll('[data-testid="seat-row"]').length,
    title: document.querySelector('[data-testid="seat-map-title"]')?.textContent,
    subtitle: document.querySelector('[data-testid="seat-map-subtitle"]')?.textContent,
    limitInfo: document.querySelector('[data-testid="seat-limit-info"]')?.textContent,
    legendItems: [...document.querySelectorAll('[data-testid="legend-item"]')].map(e=>({state: e.getAttribute('data-state'), text: e.textContent.trim()})),
  })`);
  console.log(JSON.stringify(info, null, 2));

  // row1 check: should have seats only cols 5-24 (20 seats), with accessible states for cols10-15
  const row1 = await page.evaluate(`[...document.querySelectorAll('[data-testid="seat-row"][data-row="1"] [data-testid="seat"]')].map(s=>({col:s.getAttribute('data-column'), state: s.getAttribute('data-state')}))`);
  console.log('row1', JSON.stringify(row1));

  const row1Unavail = await page.evaluate(`[...document.querySelectorAll('[data-testid="seat-row"][data-row="1"] [data-testid="seat"][data-state="unavailable"]')].length`);
  console.log('row1 unavailable count (expect occupied R1C10,R1C11 from screening1? actually screening1 occupies R3C7,R3C8,R3C9,R6C12,R6C13,R11C21,R11C22,R15C5,R15C6)', row1Unavail);

  const row15 = await page.evaluate(`[...document.querySelectorAll('[data-testid="seat-row"][data-row="15"] [data-testid="couch"]')].map(s=>({start:s.getAttribute('data-column-start'), end:s.getAttribute('data-column-end'), state:s.getAttribute('data-state')}))`);
  console.log('row15 couches', JSON.stringify(row15));

  const row11Count = await page.evaluate(`document.querySelectorAll('[data-testid="seat-row"][data-row="11"] [data-testid="seat"]').length`);
  console.log('row11 seat count (expect 24)', row11Count);

  const totalSelectable = await page.evaluate(`document.querySelectorAll('[data-testid="seat"]').length + document.querySelectorAll('[data-testid="couch"]').length`);
  console.log('total selectable (expect 308)', totalSelectable);

  await page.screenshot('/tmp/screenshot-seatmap.png');
  console.log('CONSOLE:', page.consoleMessages.join('\n'));
}).catch((err) => {
  console.error('TEST FAILED', err);
  process.exit(1);
});

