const { withPage } = require('/tmp/cdp-driver.js');

withPage(async (page) => {
  await page.navigate('http://localhost:4200/screenings/1/seats');
  await page.waitFor(`document.querySelector('[data-testid="seat-map-title"]') !== null`);
  await new Promise((r) => setTimeout(r, 500));
  await page.evaluate(`window.scrollTo(0, document.body.scrollHeight)`);
  await new Promise((r) => setTimeout(r, 200));
  await page.screenshot('/tmp/screenshot-seatmap-bottom.png');

  // select two regular seats + one couch, verify panel + colors, then exceed limit
  await page.evaluate(`document.querySelector('[data-testid="seat-row"][data-row="7"] [data-testid="seat"][data-column="11"]').click()`);
  await page.evaluate(`document.querySelector('[data-testid="seat-row"][data-row="7"] [data-testid="seat"][data-column="12"]').click()`);
  await page.evaluate(`document.querySelector('[data-testid="couch"][data-column-start="1"]').click()`);
  await new Promise((r) => setTimeout(r, 200));
  const panel = await page.evaluate(`({
    count: document.querySelector('[data-testid="selected-seats-count"]').textContent,
    rows: [...document.querySelectorAll('[data-testid="selected-seats-row"]')].map(r=>r.textContent)
  })`);
  console.log('panel', JSON.stringify(panel));

  // try to click unavailable seat (row3 col7)
  const beforeState = await page.evaluate(`document.querySelector('[data-testid="seat-row"][data-row="3"] [data-testid="seat"][data-column="7"]').getAttribute('data-state')`);
  await page.evaluate(`document.querySelector('[data-testid="seat-row"][data-row="3"] [data-testid="seat"][data-column="7"]').click()`);
  const afterState = await page.evaluate(`document.querySelector('[data-testid="seat-row"][data-row="3"] [data-testid="seat"][data-column="7"]').getAttribute('data-state')`);
  console.log('unavailable click before/after', beforeState, afterState);

  // select up to limit: currently have 2+2=4 seats selected (2 regular +1couch=2). select enough to hit 10, then exceed.
  const toSelect = [
    [7,13],[7,14],[7,15],[7,16],[7,17],[7,18]
  ];
  for (const [r,c] of toSelect) {
    await page.evaluate(`document.querySelector('[data-testid="seat-row"][data-row="${r}"] [data-testid="seat"][data-column="${c}"]').click()`);
  }
  await new Promise((r) => setTimeout(r, 200));
  const countAfter = await page.evaluate(`document.querySelector('[data-testid="selected-seats-count"]').textContent`);
  console.log('count after selecting more', countAfter);

  // now try to exceed: select one more single seat (would be 11)
  await page.evaluate(`document.querySelector('[data-testid="seat-row"][data-row="7"] [data-testid="seat"][data-column="19"]').click()`);
  await new Promise((r) => setTimeout(r, 300));
  const toast = await page.evaluate(`document.querySelector('[data-testid="toast"]')?.textContent`);
  console.log('toast after exceeding limit', toast);
  const countAfterExceed = await page.evaluate(`document.querySelector('[data-testid="selected-seats-count"]').textContent`);
  console.log('count should remain same', countAfterExceed);

  await page.screenshot('/tmp/screenshot-seatmap-selected.png');
  console.log('CONSOLE:', page.consoleMessages.join('\n'));
}).catch((err) => {
  console.error('TEST FAILED', err);
  process.exit(1);
});

