  await page.evaluate(`document.querySelector('[data-testid="continue-button"]').click()`);
  await page.waitFor(`location.pathname.includes('/summary')`);
  await new Promise((r) => setTimeout(r, 300));
  await page.evaluate(`document.querySelector('[data-testid="confirm-button"]').click()`);
  await page.waitFor(`location.pathname.includes('/checkout')`);
  await new Promise((r) => setTimeout(r, 300));

  const checkoutFields = await page.evaluate(`({
    title: document.querySelector('[data-testid="checkout-title"]')?.textContent,
    firstName: !!document.querySelector('[data-testid="first-name-input"]'),
    lastName: !!document.querySelector('[data-testid="last-name-input"]'),
    email: !!document.querySelector('[data-testid="email-input"]'),
    confirmEmail: !!document.querySelector('[data-testid="confirm-email-input"]'),
    phone: !!document.querySelector('[data-testid="phone-input"]'),
    terms: !!document.querySelector('[data-testid="terms-checkbox"]'),
    payBtn: document.querySelector('[data-testid="pay-button"]')?.textContent.trim(),
    payDisabled: document.querySelector('[data-testid="pay-button"]')?.disabled,
  })`);
  console.log('checkout fields', JSON.stringify(checkoutFields, null, 2));

  // try clicking pay with empty form -> should show errors, not submit
  await page.evaluate(`document.querySelector('[data-testid="first-name-input"]').focus()`);
  await page.evaluate(`document.querySelector('[data-testid="first-name-input"]').blur()`);
  await new Promise((r) => setTimeout(r, 200));
  const firstNameError = await page.evaluate(`document.querySelector('[data-testid="first-name-error"]')?.textContent.trim()`);
  console.log('first name error on blur empty', firstNameError);

  // fill form with mismatched emails and invalid phone
  async function setVal(testid, val) {
    await page.evaluate(`(() => {
      const el = document.querySelector('[data-testid="${testid}"]');
      const proto = Object.getPrototypeOf(el);
      const setter = Object.getOwnPropertyDescriptor(proto, 'value').set;
      setter.call(el, ${JSON.stringify(val)});
      el.dispatchEvent(new Event('input', { bubbles: true }));
    })()`);
  }
  await setVal('first-name-input', 'John');
  await setVal('last-name-input', 'Doe');
  await setVal('email-input', 'john@example.com');
  await setVal('confirm-email-input', 'mismatch@example.com');
  await setVal('phone-input', 'abc');
  await page.evaluate(`document.querySelector('[data-testid="confirm-email-input"]').dispatchEvent(new Event('blur'))`);
  await page.evaluate(`document.querySelector('[data-testid="phone-input"]').dispatchEvent(new Event('blur'))`);
  await new Promise((r) => setTimeout(r, 200));
  const errs = await page.evaluate(`({
    confirmEmailError: document.querySelector('[data-testid="confirm-email-error"]')?.textContent.trim(),
    phoneError: document.querySelector('[data-testid="phone-error"]')?.textContent.trim(),
    payDisabled: document.querySelector('[data-testid="pay-button"]')?.disabled,
  })`);
  console.log('mismatch/invalid errors', JSON.stringify(errs, null, 2));

  // fix email and phone, check terms, submit
  await setVal('confirm-email-input', 'john@example.com');
  await setVal('phone-input', '+48123456789');
  await page.evaluate(`document.querySelector('[data-testid="terms-checkbox"] input').click()`);
  await new Promise((r) => setTimeout(r, 200));
  const payDisabledAfterFix = await page.evaluate(`document.querySelector('[data-testid="pay-button"]')?.disabled`);
  console.log('pay disabled after fix', payDisabledAfterFix);

  await page.evaluate(`document.querySelector('[data-testid="pay-button"]').click()`);
  await page.waitFor(`location.pathname.includes('/confirmation')`, 8000).catch(e => console.log('did not navigate to confirmation', e.message));
  await new Promise((r) => setTimeout(r, 500));
  console.log('url after pay', await page.evaluate('location.href'));
  const confirmation = await page.evaluate(`({
    heading: document.querySelector('[data-testid="confirmation-heading"]')?.textContent,
    message: document.querySelector('[data-testid="confirmation-message"]')?.textContent,
  })`);
  console.log('confirmation', JSON.stringify(confirmation, null, 2));

  await page.screenshot('/tmp/screenshot-confirmation.png');
  console.log('CONSOLE:', page.consoleMessages.join('\n'));
}).catch((err) => {
  console.error('TEST FAILED', err);
  process.exit(1);
});

