const { withPage } = require('/tmp/cdp-driver.js');

withPage(async (page) => {
  await page.navigate('http://localhost:4200/screenings/1/seats');
  await page.waitFor(`document.querySelector('[data-testid="seat-map-title"]') !== null`);
  await new Promise((r) => setTimeout(r, 300));
  await page.evaluate(`document.querySelector('[data-testid="seat-row"][data-row="7"] [data-testid="seat"][data-column="11"]').click()`);
  await page.evaluate(`document.querySelector('[data-testid="continue-button"]').click()`);
  await page.waitFor(`location.pathname.includes('/summary')`);
  await page.evaluate(`document.querySelector('[data-testid="confirm-button"]').click()`);
  await page.waitFor(`location.pathname.includes('/checkout')`);
  await new Promise((r) => setTimeout(r, 300));

  await page.evaluate(`document.querySelector('[data-testid="first-name-input"]').dispatchEvent(new FocusEvent('blur', {bubbles:true}))`);
  await new Promise((r) => setTimeout(r, 200));
  const err1 = await page.evaluate(`document.querySelector('[data-testid="first-name-error"]')?.textContent`);
  console.log('err1 (expect required msg)', err1);

  // click pay with empty form -> all errors + toast
  await page.navigate('http://localhost:4200/screenings/1/seats');
  await page.waitFor(`document.querySelector('[data-testid="seat-map-title"]') !== null`);
  await new Promise((r) => setTimeout(r, 300));
  await page.evaluate(`document.querySelector('[data-testid="seat-row"][data-row="7"] [data-testid="seat"][data-column="11"]').click()`);
  await page.evaluate(`document.querySelector('[data-testid="continue-button"]').click()`);
  await page.waitFor(`location.pathname.includes('/summary')`);
  await page.evaluate(`document.querySelector('[data-testid="confirm-button"]').click()`);
  await page.waitFor(`location.pathname.includes('/checkout')`);
  await new Promise((r) => setTimeout(r, 300));
  await page.evaluate(`document.querySelector('[data-testid="pay-button"]').click()`);
  await new Promise((r) => setTimeout(r, 300));
  const allErrors = await page.evaluate(`({
    firstName: document.querySelector('[data-testid="first-name-error"]')?.textContent,
    lastName: document.querySelector('[data-testid="last-name-error"]')?.textContent,
    email: document.querySelector('[data-testid="email-error"]')?.textContent,
    confirmEmail: document.querySelector('[data-testid="confirm-email-error"]')?.textContent,
    terms: document.querySelector('[data-testid="terms-error"]')?.textContent,
    toast: document.querySelector('[data-testid="toast"]')?.textContent,
  })`);
  console.log('all errors after pay click on empty form', JSON.stringify(allErrors, null, 2));

  console.log('CONSOLE:', page.consoleMessages.join('\n'));
}).catch((err) => {
  console.error('TEST FAILED', err);
  process.exit(1);
});

