import { Component, inject } from '@angular/core';
import { MatButtonModule } from '@angular/material/button';
import { Router } from '@angular/router';
import { BookingService } from '../../core/booking.service';

@Component({
  selector: 'app-confirmation',
  imports: [MatButtonModule],
  templateUrl: './confirmation.component.html',
  styleUrl: './confirmation.component.scss',
})
export class ConfirmationComponent {
  private readonly router = inject(Router);
  private readonly bookingService = inject(BookingService);

  readonly email = this.bookingService.booking().email ?? '';

  continue(): void {
    this.bookingService.clear();
    this.router.navigateByUrl('/');
  }
}
<h1 data-testid="confirmation-heading">Payment successful</h1>
<p data-testid="confirmation-message">Your tickets will be sent shortly to {{ email }}</p>
<button mat-flat-button data-testid="confirmation-continue-button" (click)="continue()">Continue</button>

