const { withPage } = require('/tmp/cdp-driver.js');

withPage(async (page) => {
  // 1. Direct access to summary/checkout/confirmation without a booking -> redirect to /
  for (const path of ['/screenings/1/summary', '/screenings/1/checkout', '/confirmation']) {
    await page.navigate('http://localhost:4200' + path);
    await new Promise((r) => setTimeout(r, 500));
    console.log(path, '-> redirected to', await page.evaluate('location.pathname'));
  }

  // 2. Form persistence: fill partial values, go back to summary, return to checkout, values should remain
  await page.navigate('http://localhost:4200/screenings/1/seats');
  await page.waitFor(`document.querySelector('[data-testid="seat-map-title"]') !== null`);
  await new Promise((r) => setTimeout(r, 300));
  await page.evaluate(`document.querySelector('[data-testid="seat-row"][data-row="7"] [data-testid="seat"][data-column="11"]').click()`);
  await page.evaluate(`document.querySelector('[data-testid="continue-button"]').click()`);
  await page.waitFor(`location.pathname.includes('/summary')`);
  await page.evaluate(`document.querySelector('[data-testid="confirm-button"]').click()`);
  await page.waitFor(`location.pathname.includes('/checkout')`);
  await new Promise((r) => setTimeout(r, 300));

  async function setVal(testid, val) {
    await page.evaluate(`(() => {
      const el = document.querySelector('[data-testid="${testid}"]');
      const proto = Object.getPrototypeOf(el);
      const setter = Object.getOwnPropertyDescriptor(proto, 'value').set;
      setter.call(el, ${JSON.stringify(val)});
      el.dispatchEvent(new Event('input', { bubbles: true }));
    })()`);
  }
  await setVal('first-name-input', 'Jane');
  await setVal('email-input', 'jane@example.com');
  await new Promise((r) => setTimeout(r, 200));

  await page.evaluate(`document.querySelector('[data-testid="checkout-back-button"]').click()`);
  await page.waitFor(`location.pathname.includes('/summary')`);
  await new Promise((r) => setTimeout(r, 200));
  await page.evaluate(`document.querySelector('[data-testid="confirm-button"]').click()`);
  await page.waitFor(`location.pathname.includes('/checkout')`);
  await new Promise((r) => setTimeout(r, 300));
  const restored = await page.evaluate(`({
    firstName: document.querySelector('[data-testid="first-name-input"]').value,
    email: document.querySelector('[data-testid="email-input"]').value,
    firstNameErrorVisible: !!document.querySelector('[data-testid="first-name-error"]'),
  })`);
  console.log('restored values after back+forward', JSON.stringify(restored, null, 2));

  console.log('CONSOLE:', page.consoleMessages.join('\n'));
}).catch((err) => {
  console.error('TEST FAILED', err);
  process.exit(1);
});

